	{long: "config", short: "c", takesValue: true, isBool: false},
	{long: "unwrap-exports", takesValue: false, isBool: true},
	{long: "js-tsconfig-paths", takesValue: false, isBool: true},
	{long: "js-workspaces", takesValue: false, isBool: true},
	{long: "python-exclude-conditional-imports", takesValue: false, isBool: true},
	{long: "only", takesValue: true, isBool: false},
	{long: "exclude", takesValue: true, isBool: false},
	{long: "help", short: "h", takesValue: false, isBool: true},
}

