var entropyFlagDefs = []flagDef{
	{long: "enable-gui", takesValue: false, isBool: true},
	{long: "no-browser-open", takesValue: false, isBool: true},
	{long: "render-path", takesValue: true, isBool: false},
}

var treeFlagDefs = []flagDef{
	{long: "json", takesValue: false, isBool: true},
}

var explainFlagDefs = []flagDef{
	{long: "overlap-left", short: "l", takesValue: false, isBool: true},
	{long: "overlap-right", short: "r", takesValue: false, isBool: true},
}

func findLongFlag(defs []flagDef, name string) *flagDef {
	for i := range defs {
		if defs[i].long == name {
			return &defs[i]
		}
	}
	return nil
}

func findShortFlag(defs []flagDef, ch byte) *flagDef {
	for i := range defs {
		if defs[i].short != "" && defs[i].short[0] == ch {
			return &defs[i]
		}
	}
	return nil
}

func allDefsFor(sub string) []flagDef {
	defs := append([]flagDef{}, globalFlagDefs...)
	switch sub {
	case "entropy", "default":
		defs = append(defs, entropyFlagDefs...)
	case "tree":
		defs = append(defs, treeFlagDefs...)
	case "explain":
		defs = append(defs, explainFlagDefs...)
	case "check", "config", "help":
		// no extra
