					}
					pf.version = true
					pf.global.version = true
					continue
				}
				def := findShortFlag(defs, ch)
				if def == nil {
					return nil, pf, fmt.Sprintf("Error: unknown shorthand flag: '%c' in -%s", ch, shorts)
				}
				if def.takesValue {
					// 'c' takes value
					var v string
					if k+1 < len(shorts) {
						// Rest of shorts is value
						v = shorts[k+1:]
					} else {
						// Next arg is value
						if i+1 >= len(args) {
							return nil, pf, fmt.Sprintf("Error: flag needs an argument: '%c' in -%s", ch, shorts)
						}
						v = args[i+1]
						consumedNext = true
					}
					applyShortValue(&pf, ch, v)
					break // 'c' consumes rest, done with this arg
				} else {
					// Bool, set true (for help, set help)
					if def.long == "help" {
						pf.help = true
						pf.global.help = true
					} else {
						applyShortBool(&pf, ch, true, defs)
					}
					// Continue to next char (for combined like -lr)
				}
			}
			if consumedNext {
				i += 2
			} else {
				i++
			}
			continue
		} else {
			// Positional (including "-" alone)
			positionals = append(positionals, arg)
			i++
			continue
		}
	}
	return positionals, pf, ""
}

func applyLongValue(pf *parsedFlags, name, val string) {
	switch name {
	case "config":
		pf.global.config = val
	case "only":
		pf.global.only = append(pf.global.only, val)
	case "exclude":
		pf.global.exclude = append(pf.global.exclude, val)
	case "render-path":
		pf.entropy.renderPath = val
	}
}

func applyLongBool(pf *parsedFlags, name string, b bool) {
	switch name {
	case "unwrap-exports":
		pf.global.unwrapExports = b
	case "js-tsconfig-paths":
		pf.global.jsTsconfigPaths = b
	case "js-workspaces":
		pf.global.jsWorkspaces = b
	case "python-exclude-conditional-imports":
		pf.global.pythonExcludeConditionalImports = b
	case "enable-gui":
		pf.entropy.enableGui = b
	case "no-browser-open":
		pf.entropy.noBrowserOpen = b
	case "json":
		pf.tree.json = b
	case "overlap-left":
		pf.explain.overlapLeft = b
	case "overlap-right":
		pf.explain.overlapRight = b
	}
}

func applyShortValue(pf *parsedFlags, ch byte, val string) {
	if ch == 'c' {
		pf.global.config = val
	}
}

func applyShortBool(pf *parsedFlags, ch byte, b bool, defs []flagDef) {
	def := findShortFlag(defs, ch)
	if def == nil {
		return
	}
	applyLongBool(pf, def.long, b)
}
