package language

import (
	"os"
	"path/filepath"
	"strings"
)

// Supported extensions
var supportedExts = map[string]bool{
	".py":  true,
	".js":  true,
	".ts":  true,
	".jsx": true,
	".tsx": true,
	".mjs": true,
	".cjs": true,
	".rs":  true,
	".go":  true,
}

func IsSupported(path string) bool {
	ext := strings.ToLower(filepath.Ext(path))
	return supportedExts[ext]
}

func LangFromPath(path string) string {
	ext := strings.ToLower(filepath.Ext(path))
	switch ext {
	case ".py":
		return "python"
	case ".js", ".ts", ".jsx", ".tsx", ".mjs", ".cjs":
		return "js"
	case ".rs":
		return "rust"
	case ".go":
		return "go"
	default:
		return ""
	}
}

// FindProjectRoot walks upwards from fileDir looking for markers.
// markers is list of filenames to check. Returns root dir (absolute) or "" if not found.
func FindProjectRoot(filePath string, markers []string) string {
	dir := filepath.Dir(filePath)
	absDir, _ := filepath.Abs(dir)
	for {
		for _, m := range markers {
			p := filepath.Join(absDir, m)
			if _, err := os.Stat(p); err == nil {
				return absDir
			}
		}
		parent := filepath.Dir(absDir)
		if parent == absDir {
			return ""
		}
		absDir = parent
	}
}

// FindNearestFile walks upwards looking for a specific file, returns its path or "".
func FindNearestFile(filePath, filename string) string {
	dir := filepath.Dir(filePath)
	absDir, _ := filepath.Abs(dir)
	for {
		p := filepath.Join(absDir, filename)
		if _, err := os.Stat(p); err == nil {
			return p
		}
		parent := filepath.Dir(absDir)
		if parent == absDir {
			return ""
		}
		absDir = parent
	}
}

// CountLoc counts newlines in file content.
func CountLoc(content []byte) int {
	n := 0
	for _, b := range content {
		if b == '\n' {
			n++
		}
	}
	return n
}
