func removeSameLineTriple(line, triple string) string {
	// Remove pairs of triple on same line (e.g., `x = """..."""` => `x = `)
	// Find pairs and remove content between (including triples)
	for {
		start := strings.Index(line, triple)
		if start == -1 {
			break
		}
		end := strings.Index(line[start+len(triple):], triple)
		if end == -1 {
			break // odd, leave for state handling
		}
		end += start + len(triple)
		line = line[:start] + line[end+len(triple):]
	}
	return line
}

func stripPyLine(line string) string {
	// Remove single/double quoted strings and # comments (first # not in string)
	var out strings.Builder
	n := len(line)
	i := 0
	inSingle := false
	inDouble := false
	escaped := false
	for i < n {
		c := line[i]
		if escaped {
			escaped = false
			// Inside string, skip? Actually for import detection, we want to remove strings entirely (replace with space?).
			// If in string, don't output string content (to avoid detecting `import` inside string).
			// If not in string, `\\` is just char, output?
			if inSingle || inDouble {
				// Skip escaped char inside string (don't output)
			} else {
				out.WriteByte(c)
			}
			i++
			continue
		}
		if c == '\\' {
			if inSingle || inDouble {
				escaped = true
				i++
				continue
			}
			out.WriteByte(c)
			i++
			continue
		}
		if inSingle {
			if c == '\'' {
				inSingle = false
			}
			// Skip string content (don't output)
			i++
			continue
		}
		if inDouble {
			if c == '"' {
				inDouble = false
			}
			i++
			continue
		}
		// Not in string
		if c == '\'' {
			inSingle = true
			i++
			continue
		}
		if c == '"' {
			inDouble = true
			i++
			continue
		}
		if c == '#' {
			// Comment start, ignore rest of line
			break
		}
		out.WriteByte(c)
		i++
	}
	return out.String()
}

func parseFromImportYs(importPart string) []string {
	s := strings.TrimSpace(importPart)
	if s == "" || s == "(" {
		return nil
	}
	// Remove surrounding parentheses? e.g., "(a, b)" or "(a,\n" (multiline start, but we only see first line "("? Actually first line is "from x import (", importPart "(" - handled above as nil. For single-line "(a, b)", s "(a, b)" - strip parens.
	s = strings.TrimSpace(s)
	if strings.HasPrefix(s, "(") && strings.HasSuffix(s, ")") {
		s = s[1 : len(s)-1]
	} else if strings.HasPrefix(s, "(") {
		// Unclosed "(" (multiline start with some on same line? e.g., "from x import (a," - first line importPart "(a,". Strip "(".
		s = strings.TrimSpace(s[1:])
		// If ends with ","? Keep, split will handle.
	}
	// Remove trailing ")"? For last line of multiline? But we process line-by-line, last line ")" alone is not an import (since it doesn't start with "from"), so ignored. Good.
	// Split by comma
	parts := strings.Split(s, ",")
	var res []string
	for _, p := range parts {
		p = strings.TrimSpace(p)
		// Remove "(" / ")" leftover? e.g., "(a" => "a", "b)" => "b"
		p = strings.Trim(p, "()")
		p = strings.TrimSpace(p)
		if p != "" {
			res = append(res, p)
		}
	}
	return res
}

// resolveAbsolute resolves `import X.Y.Z` (absolute) to file.
// Returns abs path or "" if not found (stdlib, nonexistent, etc.)
func (p *PythonLanguage) resolveAbsolute(modPath, importerAbs string) (string, string) {
	if p.root == "" {
		return "", ""
	}
	// modPath like "pkg.helper", "pkg.sub.inner", "os", "pkg"
	parts := strings.Split(modPath, ".")
	// Try as file: root/parts... .py
	filePath := filepath.Join(append([]string{p.root}, parts...)...) + ".py"
	// Actually need to join: root + parts joined by "/" + ".py"
	rel := filepath.Join(parts...) + ".py"
	abs := filepath.Join(p.root, rel)
	if _, err := os.Stat(abs); err == nil {
		return abs, ""
	}
	// Try as package: root/parts.../__init__.py
	rel2 := filepath.Join(append(parts, "__init__.py")...)
	abs2 := filepath.Join(p.root, rel2)
	// For join with parts + __init__: filepath.Join(parts..., "__init__.py")? Actually parts is []string, need to expand.
	// Use filepath.Join with slice: need to convert to args. Simplify: strings.Join(parts, "/") + "/__init__.py"
	rel2s := strings.Join(parts, string(filepath.Separator)) + string(filepath.Separator) + "__init__.py"
	abs2 = filepath.Join(p.root, rel2s)
	_ = rel2
	_ = abs2
	if _, err := os.Stat(abs2); err == nil {
		return abs2, ""
	}
	return "", ""
}

// resolveFromModule resolves `from X` (X can be absolute or relative with dots) to file (for `*` or no Ys case, or for Y that is not a file).
// Returns abs path of X's file (__init__ or .py) or "".
func (p *PythonLanguage) resolveFromModule(modPart, importerAbs string) (string, string) {
	if p.root == "" {
		return "", ""
	}
	if strings.HasPrefix(modPart, ".") {
		// Relative
		return p.resolveRelative(modPart, "", importerAbs)
	}
	// Absolute
	return p.resolveAbsolute(modPart, importerAbs)
}

