	jsExportNamedRe = regexp.MustCompile(`export\s*\{([^}]*)\}\s*from\s*['"]([^'"]+)['"]`)
	jsExportStarRe  = regexp.MustCompile(`export\s*\*\s*(?:as\s+\w+\s*)?from\s*['"]([^'"]+)['"]`)
