func stripJsComments(s string) string {
	var out strings.Builder
	n := len(s)
	i := 0
	inSingle := false
	inDouble := false
	inTemplate := false // `...` with ${}?
	inLineComment := false
	inBlockComment := false
	escaped := false
	for i < n {
		c := s[i]
		if inLineComment {
			if c == '\n' {
				inLineComment = false
				out.WriteByte(c)
			}
			i++
			continue
		}
		if inBlockComment {
			if c == '*' && i+1 < n && s[i+1] == '/' {
				inBlockComment = false
				i += 2
				continue
			}
			if c == '\n' {
				out.WriteByte(c)
			}
			i++
			continue
		}
		if inSingle {
			out.WriteByte(c)
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '\'' {
				inSingle = false
			}
			i++
			continue
		}
		if inDouble {
			out.WriteByte(c)
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '"' {
				inDouble = false
			}
			i++
			continue
		}
		if inTemplate {
			out.WriteByte(c)
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '`' {
				inTemplate = false
			}
			// Note: ${} inside template could contain strings/comments? Ignore for simplicity (treat as template content, not code). For import detection, imports inside ${} are unlikely.
			i++
			continue
		}
		// Not in string/comment
		if c == '\'' {
			inSingle = true
			out.WriteByte(c)
			i++
			continue
		}
		if c == '"' {
			inDouble = true
			out.WriteByte(c)
			i++
			continue
		}
		if c == '`' {
			inTemplate = true
			out.WriteByte(c)
			i++
			continue
		}
		if c == '/' && i+1 < n {
			if s[i+1] == '/' {
				inLineComment = true
				i += 2
				continue
			}
			if s[i+1] == '*' {
				inBlockComment = true
				i += 2
				continue
			}
		}
		out.WriteByte(c)
		i++
	}
	return out.String()
}

