				out.WriteByte(c)
			}
			i++
			continue
		}
		if inSingle {
			out.WriteByte(c)
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '\'' {
				inSingle = false
			}
			i++
			continue
		}
		if inDouble {
			out.WriteByte(c)
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '"' {
				inDouble = false
			}
			i++
			continue
		}
		if inTemplate {
			out.WriteByte(c)
			if escaped {
				escaped = false
			} else if c == '\\' {
				escaped = true
			} else if c == '`' {
				inTemplate = false
			}
			// Note: ${} inside template could contain strings/comments? Ignore for simplicity (treat as template content, not code). For import detection, imports inside ${} are unlikely.
			i++
			continue
		}
		// Not in string/comment
		if c == '\'' {
			inSingle = true
			out.WriteByte(c)
			i++
			continue
		}
		if c == '"' {
			inDouble = true
			out.WriteByte(c)
			i++
			continue
		}
		if c == '`' {
			inTemplate = true
			out.WriteByte(c)
			i++
			continue
		}
		if c == '/' && i+1 < n {
			if s[i+1] == '/' {
				inLineComment = true
				i += 2
				continue
			}
			if s[i+1] == '*' {
				inBlockComment = true
				i += 2
				continue
			}
		}
		out.WriteByte(c)
		i++
	}
	return out.String()
}

func (j *JsLanguage) ParseFile(absPath string) ([]string, []string, error) {
	data, err := os.ReadFile(absPath)
	if err != nil {
		return nil, nil, err
	}
	content := string(data)
	stripped := stripJsComments(content)
	// Collect import specifiers in order (as they appear)
	// Need to find all matches of each regex with positions, then sort by position to preserve import order (for entropy/check ordering).
	type match struct {
		pos int
		spec string
	}
	var matches []match
	for _, re := range []*regexp.Regexp{jsImportRe, jsExportFromRe, jsRequireRe, jsDynamicImportRe} {
		locs := re.FindAllStringSubmatchIndex(stripped, -1)
		subs := re.FindAllStringSubmatch(stripped, -1)
		for idx, loc := range locs {
			if len(loc) >= 4 {
				// loc[2], loc[3] are start/end of first submatch (spec)
				_ = loc
				spec := subs[idx][1]
				pos := loc[0] // start of whole match
				matches = append(matches, match{pos: pos, spec: spec})
			}
		}
	}
	// Sort by pos
	for i := 0; i < len(matches); i++ {
		for k := i+1; k < len(matches); k++ {
			if matches[k].pos < matches[i].pos {
				matches[i], matches[k] = matches[k], matches[i]
