	var deps []string
	var softErrors []string
	seenDep := make(map[string]bool)
	addDep := func(abs string) {
		if abs == "" || abs == absPath {
			return
		}
		if !seenDep[abs] {
			seenDep[abs] = true
			deps = append(deps, abs)
		}
	}
	for _, m := range matches {
		spec := m.spec
		if seenSpec[spec] {
			// Already processed this specifier? But need to handle unwrap? For unwrap, same spec with different symbols? e.g., `import { a } from './x'; import { b } from './x';` (same spec, different symbols, unwrap might resolve to different files? Unlikely, since same specifier resolves to same file (or unwrapped to different? For re-exports with different symbols mapping to different files? Possible: `./x` re-exports `a` from `./a` and `b` from `./b`, then `import { a } from './x'` unwraps to ./a, `import { b } from './x'` unwraps to ./b (different files, same spec). If we dedupe by spec, we'd miss second file. So don't dedupe by spec when unwrap enabled? For non-unwrap, same spec always resolves to same file, so dedupe is fine. For unwrap, need per-symbol.
			// For simplicity, when unwrap disabled, dedupe by spec. When enabled, don't dedupe (process each occurrence with its symbols).
			if !j.unwrapExports {
				continue
			}
		}
		seenSpec[spec] = true
		// Resolve spec
		if strings.HasPrefix(spec, ".") {
			// Relative import
			resolved, errStr := j.resolveRelative(absPath, spec)
			if errStr != "" {
				// Check if already have this error? Original: for multiple same unresolved specs, does it list error once or multiple? Likely once (since errors is list per file, deduped? Or per spec? For `import "./nonexistent"; import "./nonexistent";` twice, errors would be one or two? Probably one (deduped) or two (duplicate)? Need to probe.
				// For now, dedupe errors.
				found := false
				for _, e := range softErrors {
					if e == errStr {
						found = true
						break
					}
				}
				if !found {
					softErrors = append(softErrors, errStr)
				}
				continue
			}
			if resolved == "" {
				continue
			}
			// Handle unwrapExports: if enabled, try to unwrap re-exports
			if j.unwrapExports {
				unwrapped := j.unwrap(absPath, resolved, spec, stripped, m.pos)
