				// Our unwrap function should return list of files (could be multiple).
				for _, u := range unwrapped {
					addDep(u)
				}
				// If unwrapped is empty (no re-export? Or not a re-export file?), fall back to resolved?
				// Actually for non-re-export files (e.g., normal file with no re-exports), unwrap should just return resolved (no unwrapping).
				// Our unwrap should handle that: if resolved file is not a re-exporter for the imported symbols, return [resolved].
				continue
			}
			addDep(resolved)
		} else {
