}

func matchTsPath(pat, spec string) (bool, string) {
	// pat can contain single * (wildcard). e.g., "@/*" matches "@/foo" with captured "foo". "@utils/*" matches "@utils/helper" with "helper".
	// Exact match (no *): pat == spec => true, "".
	if !strings.Contains(pat, "*") {
		if pat == spec {
			return true, ""
		}
		return false, ""
	}
	// With *: split into prefix/suffix
	parts := strings.Split(pat, "*")
	if len(parts) != 2 {
		// Multiple *: not supported? Return false.
		return false, ""
	}
	prefix, suffix := parts[0], parts[1]
	if !strings.HasPrefix(spec, prefix) || !strings.HasSuffix(spec, suffix) {
		return false, ""
	}
	captured := spec[len(prefix) : len(spec)-len(suffix)]
	// Captured should not contain "/"? Actually "*" can match across "/"? In tsconfig, "*" matches any (including "/")? Likely yes. So allow.
	return true, captured
}

