func (j *JsLanguage) loadPackage(pkgPath string) *packageJson {
	if cached, ok := j.packageCache[pkgPath]; ok {
		return cached
	}
	data, err := os.ReadFile(pkgPath)
	if err != nil {
		j.packageCache[pkgPath] = nil
		return nil
	}
	var raw map[string]interface{}
	if err := json.Unmarshal(data, &raw); err != nil {
		j.packageCache[pkgPath] = nil
		return nil
	}
	name, _ := raw["name"].(string)
	var ws []string
	if v, ok := raw["workspaces"]; ok {
		switch vv := v.(type) {
		case []interface{}:
			for _, e := range vv {
				if s, ok := e.(string); ok {
					ws = append(ws, s)
				}
			}
		case map[string]interface{}:
			// Yarn workspaces as object: {packages: [...]}?
			if pkgs, ok := vv["packages"].([]interface{}); ok {
				for _, e := range pkgs {
					if s, ok := e.(string); ok {
						ws = append(ws, s)
					}
				}
			}
		}
	}
	pkg := &packageJson{Name: name, Workspaces: ws, Dir: filepath.Dir(pkgPath)}
	j.packageCache[pkgPath] = pkg
	return pkg
}

