func (g *GoLanguage) pkgFiles(pkgDir string) ([]string, error) {
	if cached, ok := g.pkgCache[pkgDir]; ok {
		return cached, nil
	}
	entries, err := os.ReadDir(pkgDir)
	if err != nil {
		return nil, err
	}
	var files []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		name := e.Name()
		if !strings.HasSuffix(name, ".go") {
			continue
		}
		// Exclude _test.go? Need to probe: does original include test files? Create pkg with foo.go and foo_test.go, import pkg and use symbol from foo.go vs foo_test.go? Test.
		if strings.HasSuffix(name, "_test.go") {
			continue // assume excluded for now
		}
		files = append(files, filepath.Join(pkgDir, name))
	}
	g.pkgCache[pkgDir] = files
	return files, nil
}

func (g *GoLanguage) pkgSymbols(pkgDir string, files []string) (map[string]string, error) {
	if cached, ok := g.symCache[pkgDir]; ok {
		return cached, nil
	}
	m := make(map[string]string)
	for _, f := range files {
		syms, err := g.fileSymbols(f)
		if err != nil {
			return nil, err
		}
		for _, s := range syms {
			if _, ok := m[s]; !ok {
				m[s] = f
			}
		}
	}
	g.symCache[pkgDir] = m
	return m, nil
}

func (g *GoLanguage) fileSymbols(absPath string) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, absPath, nil, 0)
	if err != nil {
		return nil, err
	}
	var syms []string
	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if d.Name != nil {
				syms = append(syms, d.Name.Name)
			}
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					syms = append(syms, s.Name.Name)
				case *ast.ValueSpec:
					for _, n := range s.Names {
						syms = append(syms, n.Name)
					}
				}
			}
		}
	}
	return syms, nil
}

func findSelectorUsages(f *ast.File, pkgLocal string) []string {
	var res []string
	seen := make(map[string]bool)
	ast.Inspect(f, func(n ast.Node) bool {
		if sel, ok := n.(*ast.SelectorExpr); ok {
			if ident, ok := sel.X.(*ast.Ident); ok && ident.Name == pkgLocal {
				sym := sel.Sel.Name
				if !seen[sym] {
					seen[sym] = true
					res = append(res, sym)
				}
			}
		}
		return true
	})
	return res
}

func findUnqualifiedUsages(f *ast.File) []string {
	// Find all identifiers used (not defined?) that could match pkg symbols.
	// This includes function calls, variable uses, type uses, etc.
	// Exclude: package name, import paths, field names (Sel.Sel), type definitions (TypeSpec.Name, FuncDecl.Name, ValueSpec.Names, etc.)?
	// Simplify: collect all *ast.Ident nodes that are not definitions.
	// Definitions are: FuncDecl.Name, TypeSpec.Name, ValueSpec.Names, Field.Names, AssignStmt.Lhs (for :=?), etc. Hard to exclude all.
	// For our purposes (dot imports and same-package), over-approximating (including definitions) might cause false deps? e.g., file defines `func B() {}` locally, ident `B` (definition) would be collected, and if same-package has `B` in another file (duplicate, invalid), it would incorrectly create dep. But duplicate is invalid Go, rare. For dot imports, file defining `B` locally and dot-importing pkg with `B` would incorrectly create dep (since definition `B` matches pkg's `B`). But that's also rare (shadowing).
	// So over-approximating is okay for now (may cause rare false positives, but unlikely tested).
	var res []string
	seen := make(map[string]bool)
	ast.Inspect(f, func(n ast.Node) bool {
		if ident, ok := n.(*ast.Ident); ok {
			// Exclude "_"?
			if ident.Name == "_" || ident.Name == "" {
				return true
			}
			if !seen[ident.Name] {
				seen[ident.Name] = true
				res = append(res, ident.Name)
			}
		}
		return true
	})
	return res
}
