package spinner

import (
	"fmt"
	"os"
	"time"
)

type Spinner struct {
	total int
	start time.Time
}

func New(total int) *Spinner {
	s := &Spinner{total: total, start: time.Now()}
	fmt.Fprintf(os.Stderr, "\r⠋  (0 it/hr) [0s] ")
	return s
}

func (s *Spinner) Update(current, total int) {
	s.total = total
	elapsed := time.Since(s.start)
	secs := int(elapsed.Seconds())
	var rateStr string
	if elapsed.Seconds() < 0.001 {
		rateStr = "9999 it/s"
	} else {
		rate := float64(current) / elapsed.Seconds()
		rateStr = fmt.Sprintf("%.0f it/s", rate)
	}
	fmt.Fprintf(os.Stderr, "\r⠋ (%d/%d) Loading Files... (%s) [%ds] ", current, total, rateStr, secs)
}

func (s *Spinner) Finish() {
	elapsed := time.Since(s.start)
	secs := int(elapsed.Seconds())
	var rateStr string
	if elapsed.Seconds() < 0.001 {
		rateStr = "9999 it/s"
	} else {
		rate := float64(s.total) / elapsed.Seconds()
		rateStr = fmt.Sprintf("%.0f it/s", rate)
	}
	fmt.Fprintf(os.Stderr, "\r⠋ (%d/%d) Finished loading (%s) [%ds] \n", s.total, s.total, rateStr, secs)
}
