}

func isReachable(g *graph.Graph, from, to string) bool {
	// BFS from `from` to see if `to` reachable
	visited := make(map[string]bool)
	queue := []string{from}
	visited[from] = true
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == to {
			return true
		}
		for _, dep := range g.Deps[cur] {
			if !visited[dep] {
				visited[dep] = true
				queue = append(queue, dep)
			}
		}
	}
	return false
}

