	reExportMap := make(map[string]string)
	starFroms := []string{}
	for _, m := range jsExportNamedRe.FindAllStringSubmatch(resolvedContent, -1) {
		inside := m[1]
		fromSpec := m[2]
		parts := strings.Split(inside, ",")
		for _, part := range parts {
			part = strings.TrimSpace(part)
			if part == "" {
				continue
			}
			if strings.Contains(part, " as ") {
				sp := strings.Split(part, " as ")
				if len(sp) == 2 {
					exported := strings.TrimSpace(sp[1])
					reExportMap[exported] = fromSpec
				}
			} else {
				reExportMap[part] = fromSpec
			}
		}
	}
	for _, m := range jsExportStarRe.FindAllStringSubmatch(resolvedContent, -1) {
		fromSpec := m[1]
		starFroms = append(starFroms, fromSpec)
	}
	var unwrapped []string
	seen := make(map[string]bool)
	addUnwrapped := func(abs string) {
		if abs == "" || abs == resolvedAbs {
			// For local symbols (not re-exported), we still need to add resolvedAbs (to keep original dep for local symbols).
			// Our caller dedupes, so adding resolvedAbs for local is fine (will result in [resolved] + [unwrapped] for mixed? Actually for `import { local, reexported }`, unwrapped should be [resolved (for local), target (for reexported)]? Our addUnwrapped currently skips resolvedAbs (returns without adding). That's wrong for mixed case (local symbols should keep resolved).
			// Fix: allow resolvedAbs (don't skip). Remove check for == resolvedAbs.
			pass := true
			_ = pass
		}
		if abs == "" {
			return
		}
		if !seen[abs] {
			seen[abs] = true
			unwrapped = append(unwrapped, abs)
		}
	}
	// Redefine to allow resolvedAbs
	seen2 := make(map[string]bool)
	unwrapped = nil
	add2 := func(abs string) {
		if abs == "" {
			return
		}
		if !seen2[abs] {
			seen2[abs] = true
			unwrapped = append(unwrapped, abs)
		}
	}
	_ = addUnwrapped
	for _, sym := range symbols {
		if fromSpec, ok := reExportMap[sym]; ok {
			target := j.resolveFromSpec(resolvedAbs, fromSpec)
			if target != "" {
				final := j.traceReExport(target, sym, map[string]bool{resolvedAbs: true}, fromSpec, sym)
				if final != "" {
					add2(final)
				} else {
					add2(target)
				}
			} else {
				add2(resolvedAbs)
			}
		} else {
			foundStar := false
			for _, starSpec := range starFroms {
				starFile := j.resolveFromSpec(resolvedAbs, starSpec)
				if starFile == "" {
					continue
				}
				if j.fileExportsSymbol(starFile, sym, map[string]bool{resolvedAbs: true}) {
					final := j.traceReExport(starFile, sym, map[string]bool{resolvedAbs: true}, starSpec, sym)
					if final != "" {
						add2(final)
					} else {
						add2(starFile)
					}
					foundStar = true
					break
				}
			}
			if !foundStar {
				add2(resolvedAbs)
			}
		}
	}
	if len(unwrapped) == 0 {
		return []string{resolvedAbs}
	}
	return unwrapped
}

func (j *JsLanguage) extractImportSymbols(content string, pos int, spec string) (symbols []string, isNamed, isDefault, isStar, isSideEffect bool) {
	end := strings.Index(content[pos:], ";")
	newline := strings.Index(content[pos:], "\n")
	var stmt string
	if end != -1 && (newline == -1 || end < newline) {
		stmt = content[pos : pos+end+1]
	} else if newline != -1 {
		stmt = content[pos : pos+newline]
	} else {
		stmt = content[pos:]
		if len(stmt) > 500 {
			stmt = stmt[:500]
		}
	}
	if strings.Contains(stmt, "require(") || strings.Contains(stmt, "import(") {
		return nil, false, false, false, true
	}
	if matched, _ := regexp.MatchString(`^\s*import\s*['"]`, stmt); matched {
		return nil, false, false, false, true
	}
	if strings.Contains(stmt, "*") && strings.Contains(stmt, "import") {
		if strings.HasPrefix(strings.TrimSpace(stmt), "import") {
			return nil, false, false, true, false
		}
	}
	if strings.Contains(stmt, "{") && strings.Contains(stmt, "}") {
		start := strings.Index(stmt, "{")
		end := strings.Index(stmt, "}")
		if start != -1 && end != -1 && end > start {
			inside := stmt[start+1 : end]
			parts := strings.Split(inside, ",")
			for _, p := range parts {
				p = strings.TrimSpace(p)
				if p == "" {
					continue
				}
				if strings.Contains(p, " as ") {
					sp := strings.Split(p, " as ")
					orig := strings.TrimSpace(sp[0])
					symbols = append(symbols, orig)
				} else {
					symbols = append(symbols, p)
				}
			}
			if len(symbols) > 0 {
				return symbols, true, false, false, false
			}
		}
	}
	if strings.Contains(stmt, "import") && strings.Contains(stmt, "from") {
		if !strings.Contains(stmt, "{") && !strings.Contains(stmt, "*") {
			return nil, false, true, false, false
		}
	}
	return nil, false, false, false, true
}

func (j *JsLanguage) resolveFromSpec(importerAbs, spec string) string {
	if strings.HasPrefix(spec, ".") {
		resolved, _ := j.resolveRelative(importerAbs, spec)
		return resolved
	}
	return j.resolveNonRelative(importerAbs, spec)
}

func (j *JsLanguage) traceReExport(fileAbs, symbol string, visited map[string]bool, fromSpec, origSym string) string {
	_ = fromSpec
	_ = origSym
	if visited[fileAbs] {
		return ""
	}
	visited[fileAbs] = true
	data, err := os.ReadFile(fileAbs)
	if err != nil {
		return ""
	}
	content := stripJsComments(string(data))
	for _, m := range jsExportNamedRe.FindAllStringSubmatch(content, -1) {
		inside := m[1]
		fromS := m[2]
		parts := strings.Split(inside, ",")
		for _, part := range parts {
			part = strings.TrimSpace(part)
			if part == "" {
				continue
			}
			var exported, orig string
			if strings.Contains(part, " as ") {
				sp := strings.Split(part, " as ")
				orig = strings.TrimSpace(sp[0])
				exported = strings.TrimSpace(sp[1])
			} else {
				exported = part
				orig = part
			}
			if exported == symbol {
				target := j.resolveFromSpec(fileAbs, fromS)
				if target == "" {
					return ""
				}
				if final := j.traceReExport(target, orig, visited, fromS, orig); final != "" {
					return final
				}
				return target
			}
		}
	}
	for _, m := range jsExportStarRe.FindAllStringSubmatch(content, -1) {
		fromS := m[1]
		target := j.resolveFromSpec(fileAbs, fromS)
		if target == "" {
			continue
		}
		if j.fileExportsSymbol(target, symbol, copyVisited(visited)) {
			if final := j.traceReExport(target, symbol, visited, fromS, symbol); final != "" {
				return final
			}
			return target
		}
	}
	return ""
}

func copyVisited(m map[string]bool) map[string]bool {
	n := make(map[string]bool)
	for k, v := range m {
		n[k] = v
	}
	return n
}

func (j *JsLanguage) fileExportsSymbol(fileAbs, symbol string, visited map[string]bool) bool {
	if visited[fileAbs] {
		return false
	}
	visited[fileAbs] = true
	data, err := os.ReadFile(fileAbs)
	if err != nil {
		return false
	}
	content := stripJsComments(string(data))
	localRe := regexp.MustCompile(`export\s+(?:async\s+)?(?:const|let|var|function\*?|class)\s+` + regexp.QuoteMeta(symbol) + `\b`)
	if localRe.MatchString(content) {
		return true
	}
	exportBraceRe := regexp.MustCompile(`export\s*\{([^}]*)\}`)
	for _, m := range exportBraceRe.FindAllStringSubmatchIndex(content, -1) {
		end := m[1]
		rest := content[end:]
		restTrimmed := strings.TrimLeft(rest, " \t\n\r")
		if strings.HasPrefix(restTrimmed, "from") {
			continue
		}
		inside := content[m[2]:m[3]]
		parts := strings.Split(inside, ",")
		for _, part := range parts {
			part = strings.TrimSpace(part)
			if part == "" {
				continue
			}
			var exported string
			if strings.Contains(part, " as ") {
				exported = strings.TrimSpace(strings.Split(part, " as ")[1])
			} else {
				exported = part
			}
			if exported == symbol {
				return true
			}
		}
	}
	if symbol == "default" {
		if strings.Contains(content, "export default") {
			return true
		}
	}
	for _, m := range jsExportNamedRe.FindAllStringSubmatch(content, -1) {
		inside := m[1]
		parts := strings.Split(inside, ",")
		for _, part := range parts {
			part = strings.TrimSpace(part)
			if part == "" {
				continue
			}
			var exported string
			if strings.Contains(part, " as ") {
				exported = strings.TrimSpace(strings.Split(part, " as ")[1])
			} else {
				exported = part
			}
			if exported == symbol {
				return true
			}
		}
	}
	for _, m := range jsExportStarRe.FindAllStringSubmatch(content, -1) {
		fromSpec := m[1]
		target := j.resolveFromSpec(fileAbs, fromSpec)
		if target == "" {
			continue
		}
		if j.fileExportsSymbol(target, symbol, copyVisited(visited)) {
			return true
		}
	}
	return false
}

